import java.util.*;
public class SccTest {
    static StronglyConnectedComponentsFinder<Integer> f = new KosarajuStronglyConnectedComponentsFinder<>();
    public static void main(String[] a){
        var g = new DirectedGraphBuilder<Integer>().addEdge(1,3).addEdge(1,4).addEdge(2,1).addEdge(3,2).addEdge(4,5).build();
        var r = f.find(g);
        // equals/hashCode: order-independent set semantics
        var c1 = new StronglyConnectedComponent<>(List.of(1,2,3));
        var c2 = new StronglyConnectedComponent<>(List.of(3,2,1));
        assert c1.equals(c2) && c1.hashCode()==c2.hashCode() : "set-equality";
        // O(1) lookup index
        assert r.componentContaining(2).get().contains(1) : "index lookup";
        assert r.componentContaining(99).isEmpty() : "absent vertex";
        // Iterable
        int total=0; for (var comp : r) total+=comp.size();
        assert total==5 : "iterable total "+total;
        // builder reuse safety after build()
        var b = new DirectedGraphBuilder<Integer>().addEdge(1,2);
        var gA = b.build(); b.addEdge(2,3); var gB = b.build();
        assert gA.successors(1).equals(List.of(2)) && !gA.vertices().contains(3) : "build immutability";
        assert gB.vertices().contains(3) : "second build sees new edge";
        // deep chain still fine (no recursion)
        var bc = new DirectedGraphBuilder<Integer>();
        for (int i=0;i<200000;i++) bc.addEdge(i,i+1);
        assert f.find(bc.build()).count()==200001 : "deep chain";
        System.out.println("All assertions passed");
    }
}
